import random
import struct
import base64
from typing import List

# We generate text encodings for SteamNetworkingIdentity::ParseString / SteamAPI_SteamNetworkingIdentity_ParseString
# Valid formats (URL-like):
#  - steamid: <uint64 decimal> or possibly steamid64:<uint64>
#  - ip: v4 like ip:1.2.3.4:27015 or [IPv6]:port e.g., ip:[2001:db8::1]:443 or ip:[::1]
#  - xbox: <string up to 32 chars>
#  - psn: <uint64 decimal>
#  - str: <up to 31 chars> (k_cchMaxGenericString=32 incl NUL)
#  - bytes: base64(<=32 bytes)
#  - localhost: shorthand we try: ip:[::1] or ip:127.0.0.1
# Unknown type should still parse to UnknownType: unknown:whatever
# We will compose multiple candidates and randomly pick one, biasing towards valid encodings.

MAX_OUT = 4096

SAFE_ASCII = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.:[]"


def rnd_choice(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]


def gen_ipv4(r: random.Random) -> str:
    # Favor interesting boundaries
    choices = [
        (127,0,0,1), (0,0,0,0), (255,255,255,255), (192,168,0,1), (10,0,0,1), (172,16,0,1),
        (8,8,8,8), (1,1,1,1)
    ]
    if r.random() < 0.6:
        a,b,c,d = rnd_choice(r, choices)
    else:
        a,b,c,d = (r.randrange(256), r.randrange(256), r.randrange(256), r.randrange(256))
    if r.random() < 0.7:
        port = r.randrange(0, 65536)
        return f"{a}.{b}.{c}.{d}:{port}"
    else:
        return f"{a}.{b}.{c}.{d}"


def gen_ipv6(r: random.Random) -> str:
    # Simple IPv6 patterns, include loopback and mapped
    common = [
        "::1", "::", "2001:db8::1", "fe80::1", "::ffff:192.168.0.1", "2001:0db8:85a3::8a2e:0370:7334"
    ]
    if r.random() < 0.6:
        core = rnd_choice(r, common)
    else:
        # generate hextets
        parts = []
        for _ in range(8):
            parts.append(f"{r.randrange(0, 1<<16):x}")
        core = ":".join(parts)
        # compress a run
        if r.random() < 0.5:
            idx = r.randrange(0,7)
            parts[idx:idx+2] = [""]
            core = ":".join(parts)
            core = core.replace(":::", "::")
    s = f"[{core}]"
    if r.random() < 0.7:
        s += f":{r.randrange(0,65536)}"
    return s


def gen_steamid64(r: random.Random) -> str:
    # 64-bit unsigned, avoid 0 sometimes but allow 0 occasionally
    if r.random() < 0.2:
        val = 0
    else:
        # emulate typical SteamID ranges by setting universe/type bits somewhat realistically
        val = r.getrandbits(64)
        # Ensure nonzero account id portion often
        if r.random() < 0.7:
            acc = r.randrange(1, 1<<32)
            inst = 1
            # Universe (1..4), type (1..10)
            universe = r.randrange(1,5)
            acct_type = r.randrange(1,11)
            packed = (acc & 0xffffffff) | ((inst & 0xfffff) << 32) | ((acct_type & 0xf) << 52) | ((universe & 0xff) << 56)
            val = packed
    return str(val)


def gen_xbox_pairwise(r: random.Random) -> str:
    # up to 32 chars
    length = r.randrange(1, 32)
    chars = []
    for _ in range(length):
        chars.append(rnd_choice(r, list(SAFE_ASCII)))
    return "".join(chars)


def gen_generic_string(r: random.Random) -> str:
    # up to 31 chars
    length = r.randrange(0, 31)
    # include some unicode? better keep ASCII for validity
    chars = []
    for _ in range(length):
        chars.append(rnd_choice(r, list(SAFE_ASCII)))
    return "".join(chars)


def gen_generic_bytes_b64(r: random.Random) -> str:
    n = r.randrange(0, 32)
    data = bytes(r.randrange(0,256) for _ in range(n))
    return base64.b64encode(data).decode('ascii')


def build_identity_string(r: random.Random) -> str:
    # Weighted pick of valid encodings
    kinds = [
        'steamid', 'steamid64', 'ip4', 'ip6', 'xbox', 'psn', 'str', 'bytes', 'localhost', 'unknown'
    ]
    weights = [0.18, 0.07, 0.18, 0.15, 0.06, 0.10, 0.1, 0.08, 0.05, 0.03]
    kind = r.choices(kinds, weights=weights, k=1)[0]
    if kind == 'steamid':
        return f"steamid:{gen_steamid64(r)}"
    if kind == 'steamid64':
        return f"steamid64:{gen_steamid64(r)}"
    if kind == 'ip4':
        return f"ip:{gen_ipv4(r)}"
    if kind == 'ip6':
        return f"ip:{gen_ipv6(r)}"
    if kind == 'xbox':
        return f"xbox:{gen_xbox_pairwise(r)}"
    if kind == 'psn':
        # decimal uint64
        return f"psn:{r.getrandbits(64)}"
    if kind == 'str':
        return f"str:{gen_generic_string(r)}"
    if kind == 'bytes':
        return f"bytes:{gen_generic_bytes_b64(r)}"
    if kind == 'localhost':
        return r.choice(["ip:127.0.0.1", "ip:[::1]", "ip:127.0.0.1:0", "ip:[::1]:0"])
    # unknown -> should set UnknownType but still be well-formed type:payload
    return f"unknown:{gen_generic_string(r)}"


def maybe_wrap_with_noise(r: random.Random, s: str) -> str:
    # Sometimes add surrounding whitespace or trailing spaces/newlines
    if r.random() < 0.3:
        pre = "".join(r.choice([" ", "\t"]) for _ in range(r.randrange(0, 3)))
        post = "".join(r.choice([" ", "\t"]) for _ in range(r.randrange(0, 3)))
        s = pre + s + post
    if r.random() < 0.15:
        s += "\n"
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # We will produce one or more candidate lines; fuzzer FUZZ_PARAM_STR will read a string from bytes.
    # Many fuzz harnesses split by NUL; produce a single NUL-terminated string, but simple bytes are fine.
    # We'll concatenate a few alternatives separated by newlines to increase variety if the harness reuses the buffer.
    count = 1 if r.random() < 0.6 else r.randrange(2, 6)
    parts = []
    for _ in range(count):
        s = build_identity_string(r)
        s = maybe_wrap_with_noise(r, s)
        parts.append(s)
    data = "\n".join(parts)
    b = data.encode('utf-8')
    if len(b) > MAX_OUT:
        b = b[:MAX_OUT]
    return b

import random
import string

# Target: inputs for Xbox Pairwise ID setters/getters
# Constraints: length in [1, 32], characters alphanumeric preferred
# FUZZ_PARAM_STR will read this buffer; we should return a bytes blob that
# looks like a reasonable single string. Many fuzz harnesses split corpus
# by whole buffer -> single string. We'll generate one ASCII string without
# NULs, length 1..32, using a variety of interesting patterns.

ALNUM = string.ascii_letters + string.digits

SPECIAL_SETS = [
    # Edge/interesting exact-length patterns
    lambda n: "X" * n,
    lambda n: "0" * n,
    lambda n: ("A1" * ((n + 1)//2))[:n],
    lambda n: ("z9" * ((n + 1)//2))[:n],
]

WORDS = [
    "XBOX", "PAIRWISE", "ID", "USER", "PLAYER", "STEAM", "LIVE", "GAMERTAG",
]

def _gen_len(rng: random.Random) -> int:
    # Bias toward boundaries 1 and 32, and some random middles
    choices = [1, 2, 3, 31, 32]
    if rng.random() < 0.6:
        return rng.choice(choices)
    return rng.randint(1, 32)

def _gen_alnum(rng: random.Random, n: int) -> str:
    # Mix patterns and random alnum
    if n > 0 and rng.random() < 0.5:
        pat = rng.choice(SPECIAL_SETS)
        return pat(n)
    s = []
    while len(s) < n:
        # Occasionally insert a word chunk to vary distribution
        if rng.random() < 0.25 and WORDS:
            w = rng.choice(WORDS)
            # ensure not to exceed n
            take = min(len(w), n - len(s))
            s.append(w[:take])
        else:
            # sample small chunk of alnum
            chunk_len = min(n - len(s), rng.randint(1, 6))
            s.append(''.join(rng.choice(ALNUM) for _ in range(chunk_len)))
    return ''.join(s)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    n = _gen_len(rng)
    s = _gen_alnum(rng, n)
    # Ensure constraints: 1..32, alphanumeric only
    if not (1 <= len(s) <= 32):
        s = s[:32] or "X"
    # Encode as UTF-8 bytes without terminator; harness typically uses c_str() which will add NUL
    return s.encode('ascii')

import random
import struct
from typing import List

# This generator focuses on producing valid, interesting raw byte buffers
# appropriate for multiple fuzzing stubs that consume arbitrary blobs.

MAX_SIZE = 2048

# Pattern generators

def _pattern_ascii_text(rng: random.Random, target_len: int) -> bytes:
    words = [
        b"hello", b"world", b"steam", b"networking", b"sockets", b"relay", b"ticket",
        b"certificate", b"payload", b"message", b"auth", b"p2p", b"ipv6", b"ipv4",
    ]
    seps = [b" ", b"\n", b"\r\n", b"\t", b", ", b"; ", b" | "]
    out = bytearray()
    while len(out) < target_len:
        out += rng.choice(words)
        if len(out) >= target_len:
            break
        out += rng.choice(seps)
    return bytes(out[:target_len])


def _pattern_utf8(rng: random.Random, target_len: int) -> bytes:
    codepoints = [
        0x20, 0x2E, 0x2C, 0x3A, 0x3B, 0x5F, 0x2F,
        0x00A9, 0x00AE, 0x03B1, 0x03B2, 0x03B3, 0x03C0,
        0x0410, 0x042F, 0x4E2D, 0x56FD, 0x65E5, 0x672C,
        0x1F600, 0x1F603, 0x1F604, 0x1F680,
    ]
    out = bytearray()
    while len(out) < target_len:
        cp = rng.choice(codepoints)
        out += chr(cp).encode('utf-8')
        if rng.random() < 0.1:
            out += b" "
    return bytes(out[:target_len])


def _pattern_binary_structs(rng: random.Random, target_len: int) -> bytes:
    parts: List[bytes] = []
    remaining = target_len
    while remaining > 0:
        choice = rng.randrange(4)
        if choice == 0 and remaining >= 8:
            parts.append(struct.pack('<Q', rng.getrandbits(64)))
            remaining -= 8
        elif choice == 1 and remaining >= 4:
            parts.append(struct.pack('>I', rng.getrandbits(32)))
            remaining -= 4
        elif choice == 2 and remaining >= 2:
            parts.append(struct.pack('<H', rng.getrandbits(16)))
            remaining -= 2
        else:
            chunk = bytes(rng.getrandbits(8) for _ in range(min(remaining, rng.randrange(4, 33))))
            parts.append(chunk)
            remaining -= len(chunk)
    return b''.join(parts)[:target_len]


def _pattern_repeated_blocks(rng: random.Random, target_len: int) -> bytes:
    if target_len <= 0:
        return b""
    block_sizes = [8, 16, 32, 64]
    block_size = rng.choice(block_sizes)
    block = bytes(rng.getrandbits(8) for _ in range(block_size))
    repeat = (target_len + block_size - 1) // block_size
    data = block * repeat
    data = bytearray(data[:target_len])
    # Introduce slight variations safely within bounds
    tweaks = max(1, target_len // 128)
    for _ in range(tweaks):
        idx = rng.randrange(0, target_len)
        data[idx] ^= rng.randrange(0, 256)
    return bytes(data)


def _pattern_length_prefixed(rng: random.Random, target_len: int) -> bytes:
    out = bytearray()
    while len(out) + 6 < target_len:
        t = rng.randrange(0, 256)
        max_l = max(0, min(256, target_len - len(out) - 6))
        l = rng.randrange(0, max_l + 1) if max_l > 0 else 0
        out += struct.pack('<H', t)
        out += struct.pack('<I', l)
        if l:
            out += bytes(rng.getrandbits(8) for _ in range(l))
    return bytes(out[:target_len])


def _pattern_ipv4_ipv6_like(rng: random.Random, target_len: int) -> bytes:
    out = bytearray()
    while len(out) + 8 <= target_len:
        ipv4 = rng.getrandbits(32)
        port = rng.randrange(0, 65536)
        out += struct.pack('>I', ipv4)
        out += struct.pack('>H', port)
        out += b"\x00\x00"
    while len(out) < target_len:
        out.append(rng.getrandbits(8))
    return bytes(out[:target_len])


def _choose_size(rng: random.Random) -> int:
    buckets = [0, 1, 2, 3, 7, 15, 31, 63, 127, 255, 512, 768, 1024, 1500, 2048]
    weights = [5, 5, 5, 5, 5, 6, 6, 6, 7, 8, 10, 8, 12, 4, 3]
    size = rng.choices(buckets, weights=weights, k=1)[0]
    jitter = rng.randrange(0, 17) if size > 0 else 0
    final = min(MAX_SIZE, size + jitter)
    return final


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    size = _choose_size(rng)

    strategies = [
        _pattern_ascii_text,
        _pattern_utf8,
        _pattern_binary_structs,
        _pattern_repeated_blocks,
        _pattern_length_prefixed,
        _pattern_ipv4_ipv6_like,
    ]
    primary = rng.choice(strategies)
    data = primary(rng, size)

    # Blend with a secondary strategy using identical length to avoid OOB
    if size > 256 and rng.random() < 0.4:
        secondary = rng.choice([s for s in strategies if s is not primary])
        sec = secondary(rng, size)
        # Ensure sec length matches size; if not, pad/truncate
        if len(sec) != size:
            if len(sec) < size:
                sec = sec + bytes(size - len(sec))
            else:
                sec = sec[:size]
        if len(data) != size:
            if len(data) < size:
                data = data + bytes(size - len(data))
            else:
                data = data[:size]
        mixed = bytearray(size)
        for i in range(size):
            r = rng.random()
            if r < 0.5:
                mixed[i] = data[i]
            elif r < 0.75:
                mixed[i] = sec[i]
            else:
                mixed[i] = (data[i] ^ sec[i]) & 0xFF
        data = bytes(mixed)

    # Ensure non-empty in most cases; allow empty occasionally
    if len(data) == 0 and rng.random() < 0.7:
        data = b"\x00"

    # Final cap already enforced by generation
    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]

    return data
